-- @no-txn
-- Drives its own transactions, so it opts out of the harness's isolating wrapper
-- (and keeps its own DROP-first cleanup).
--
-- `GENERATED BY DEFAULT AS IDENTITY`, dropped and re-created with no draw in the block:
-- the re-created cell sits at `0`, and 18.6 answers `4` after the rollback.
-- @setup
DROP TABLE IF EXISTS rdt_ident_d;
CREATE TABLE rdt_ident_d (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, v TEXT);
INSERT INTO rdt_ident_d (v) VALUES ('1'), ('2'), ('3');
BEGIN;
DROP TABLE rdt_ident_d;
CREATE TABLE rdt_ident_d (id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, v TEXT);
ROLLBACK;
-- @test
INSERT INTO rdt_ident_d (v) VALUES ('n1') RETURNING id;
